import{_ as t,o,c as s,a5 as a}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"类组件的更新","description":"先讲类组件的更新，函数组件的更新放到hooks中去了解； 在组件挂载之后，如果组件的props或自身的State发生了变化，如 如接口返回数据； 交互事件的发生； 会打破组件的稳定状态，从而需要更新组件，进而需要更新 dom; 组件状态 组件的数据来源有两个地方，分别是属性对象和。","frontmatter":{"title":"类组件的更新","date":"2026-08-11T00:00:00.000Z","categories":["React 系统教程"],"tags":["React","Redux","前端","教程","OneNote","原理与手写实现"],"description":"先讲类组件的更新，函数组件的更新放到hooks中去了解； 在组件挂载之后，如果组件的props或自身的State发生了变化，如 如接口返回数据； 交互事件的发生； 会打破组件的稳定状态，从而需要更新组件，进而需要更新 dom; 组件状态 组件的数据来源有两个地方，分别是属性对象和。","sidebarWeight":78,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/实现/类组件的更新 /类组件的更新.md"},"headers":[],"relativePath":"posts/React系统教程/03-原理与手写实现/类组件的更新/类组件的更新.md","filePath":"posts/React系统教程/03-原理与手写实现/类组件的更新/类组件的更新.md"}'),c={name:"posts/React系统教程/03-原理与手写实现/类组件的更新/类组件的更新.md"};function d(l,e,i,r,n,p){return o(),s("div",null,[...e[0]||(e[0]=[a('<div><h1 id="类组件的更新" tabindex="-1">类组件的更新 <a class="header-anchor" href="#类组件的更新" aria-label="Permalink to &quot;类组件的更新&quot;">​</a></h1><blockquote><p>本节目标：理解“类组件的更新”的核心思路，并能把它用于实际开发或面试表达。 先讲类组件的更新，函数组件的更新放到hooks中去了解；</p></blockquote><p>在组件挂载之后，如果组件的props或自身的State发生了变化，如</p><ul><li>如接口返回数据；</li><li>交互事件的发生；</li></ul><p>会打破组件的稳定状态，从而需要更新组件，进而需要更新<code>dom;</code></p><p><strong>组件状态</strong></p><ul><li>组件的数据来源有两个地方，分别是属性对象和状态对象</li><li>属性是父组件传递过来的；</li><li>状态是自己内部的，改变状态唯一的方式就是<code>setState</code>；；</li><li>属性和状态的变化都会影响视图更新；</li><li>不要直接修改 <code>State</code>，构造函数是唯一可以给 <code>this.state</code> 赋值的地方；</li></ul><p><strong>先了解类组件自身<strong><strong>State</strong></strong>值的变化引起的更新；</strong><strong>我们一般会在：</strong></p><ul><li><strong>事件回调</strong></li><li><strong>生命周期函数中</strong></li></ul><p><strong>更新类组件的状态，更新类组件的状态必须使用</strong><code>setState</code><strong>方法；</strong></p><p><code>State</code> 的更新会被合并 当你调用 <code>setState()</code> 的时候，<code>React</code> 会把你提供的对象合并到当前的 <code>state</code>；</p><ul><li><code>State</code> 的更新可能是异步的 <ul><li>出于性能考虑，<code>React</code> 可能会把多个 <code>setState()</code> 调用合并成一个调用</li><li>因为 <code>this.props</code> 和 <code>this.state</code> 可能会异步更新，所以你不要依赖他们的值来更新下一个状态；</li><li>可以让 <code>setState()</code> 接收一个函数而不是一个对象。这个函数用上一个 <code>state</code> 作为第一个参数；</li></ul></li></ul><p>有时异步更新，有时同步更新的原因在于两种更新方式不在同一个事件循环里；</p></div>',1)])])}const g=t(c,[["render",d]]);export{u as __pageData,g as default};
